+#[derive(Clone, Copy, Debug, PartialEq, Eq)]
+enum ConstantWrite {
+    Discard(u32),
+    Append(u32),
+}
+
+#[derive(Default)]
+struct ConstantOffsets {
+    next: u32,
+    bound: u32,
+}
+
+impl ConstantOffsets {
+    fn reset(&mut self) {
+        self.next = 0;
+        self.bound = 0;
+    }
+
+    fn allocate(&mut self) -> ConstantWrite {
+        let offset = match self.next < CONSTANT_STREAM_BYTES {
+            true => self.next,
+            false => 0,
+        };
+        self.next = offset + CONSTANT_SLOT_BYTES;
+        self.bound = offset;
+        match offset {
+            0 => ConstantWrite::Discard(offset),
+            _ => ConstantWrite::Append(offset),
+        }
+    }
+}
+
+fn constant_offsetting(device: &ID3D11Device) -> bool {
+    let mut options = D3D11_FEATURE_DATA_D3D11_OPTIONS::default();
+    let queried = unsafe {
+        device.CheckFeatureSupport(
+            D3D11_FEATURE_D3D11_OPTIONS,
+            &mut options as *mut _ as *mut std::ffi::c_void,
+            std::mem::size_of_val(&options) as u32,
+        )
+    };
+    queried.is_ok()
+        && options.ConstantBufferOffsetting.as_bool()
+        && options.MapNoOverwriteOnDynamicConstantBuffer.as_bool()
+}

