+#[test]
+fn constant_ranges_wrap_and_reset_without_changing_pixels() {
+    use aqua_core::Oklch;
+    use aqua_gpu_ref::conformance::cases::quad;
+    use aqua_gpu_ref::conformance::{compare, Session};
+    use aqua_graph::{plan_paint, Extent, PaintCommand};
