+    let _software = support::software();
+    for preference in [AdapterPreference::Warp, AdapterPreference::HighPerformance] {
+        let mut backend =
+            OffscreenBackend::with_format(preference, SurfaceFormat::Rgba16Float).unwrap();
+        eprintln!(
+            "{preference:?} constant_buffer_bytes={}",
+            aqua_gpu_d3d11::ledger::snapshot()
+                .find("constant_buffer")
+                .unwrap()
+                .line
+                .bytes
+        );
+        let mut reference = RefBackend::new();
+        let mut actual = Session::new(&mut backend);
+        let mut expected = Session::new(&mut reference);
+        for frame in 0..3 {
+            let commands: Vec<_> = (0..300)
+                .flat_map(|index| {
+                    let x = index as f32 * 4.0;
+                    let opacity = 0.2 + ((index + frame) % 17) as f32 * 0.04;
+                    [
+                        PaintCommand::PushOpacity(opacity),
+                        quad(x, 0.0, 3.0, 6.0, "#ff0000", 1.0, 0.0, 0.0),
+                        quad(x + 1.0, 2.0, 3.0, 6.0, "#0000ff", 1.0, 0.0, 0.0),
+                        PaintCommand::PopOpacity,
+                    ]
+                })
+                .collect();
+            let plan = plan_paint(
+                Extent {
+                    width: 1200,
+                    height: 8,
+                },
+                Oklch::TRANSPARENT,
+                &commands,
+            )
+            .unwrap();
+            assert!(plan.passes.len() > 512);
+            let expected = expected.render(&plan).unwrap();
+            let actual = actual.render(&plan).unwrap();
+            let comparison = compare(&plan, &expected, &actual, Tolerance::default());
+            assert!(
+                comparison.passed(),
+                "{preference:?} frame {frame}: {comparison:?}"
+            );
+        }
+    }
