+use super::{ConstantOffsets, ConstantWrite, CONSTANT_SLOT_BYTES, CONSTANT_STREAM_BYTES};
+
+#[test]
+fn constant_writes_append_without_overwriting_earlier_slots() {
+    let mut offsets = ConstantOffsets::default();
+    assert_eq!(offsets.allocate(), ConstantWrite::Discard(0));
+    for offset in (CONSTANT_SLOT_BYTES..CONSTANT_STREAM_BYTES).step_by(CONSTANT_SLOT_BYTES as usize)
+    {
+        assert_eq!(offsets.allocate(), ConstantWrite::Append(offset));
+        assert_eq!(offsets.bound, offset);
+        assert!(offset + CONSTANT_SLOT_BYTES <= CONSTANT_STREAM_BYTES);
+    }
+    assert_eq!(offsets.allocate(), ConstantWrite::Discard(0));
+    assert_eq!(
+        offsets.allocate(),
+        ConstantWrite::Append(CONSTANT_SLOT_BYTES)
+    );
+}
+
+#[test]
+fn a_new_frame_discards_before_reusing_the_first_slot() {
+    let mut offsets = ConstantOffsets::default();
+    offsets.allocate();
+    offsets.allocate();
+    offsets.reset();
+    assert_eq!(offsets.bound, 0);
+    assert_eq!(offsets.allocate(), ConstantWrite::Discard(0));
+    assert_eq!(
+        offsets.allocate(),
+        ConstantWrite::Append(CONSTANT_SLOT_BYTES)
+    );
+}
