+#[test]
+fn legacy_and_range_constants_render_the_same_after_clearing_state() {
+    use aqua_core::Oklch;
+    use aqua_gpu_ref::conformance::cases::quad;
+    use aqua_graph::{plan_paint, Extent, PaintCommand};
+    use windows::Win32::Graphics::Direct3D11::*;
+    use windows::Win32::Graphics::Dxgi::Common::*;
+
+    use super::{dynamic_buffer, SceneRenderer, CONSTANT_FLOATS};
+    use crate::hal::{Core, DeviceOptions};
+    use crate::scene::{
+        read_texture, AdapterPreference, PersistentTextures, SceneOptions, SceneTarget,
+    };
+
+    let core =
+        Core::new(DeviceOptions::default().with_preference(AdapterPreference::Warp)).unwrap();
+    let device = core.device();
+    let context = core.context();
+    let extent = Extent {
+        width: 24,
+        height: 16,
+    };
+    let desc = D3D11_TEXTURE2D_DESC {
+        Width: extent.width,
+        Height: extent.height,
+        MipLevels: 1,
+        ArraySize: 1,
+        Format: DXGI_FORMAT_B8G8R8A8_UNORM,
+        SampleDesc: DXGI_SAMPLE_DESC {
+            Count: 1,
+            Quality: 0,
+        },
+        Usage: D3D11_USAGE_DEFAULT,
+        BindFlags: D3D11_BIND_RENDER_TARGET.0 as u32,
+        ..D3D11_TEXTURE2D_DESC::default()
+    };
+    let mut texture = None;
+    unsafe {
+        device
+            .CreateTexture2D(&desc, None, Some(&mut texture))
+            .unwrap()
+    };
+    let texture = texture.unwrap();
+    let mut rtv = None;
+    unsafe {
+        device
+            .CreateRenderTargetView(&texture, None, Some(&mut rtv))
+            .unwrap()
+    };
+    let rtv = rtv.unwrap();
+    let target = SceneTarget {
+        texture: &texture,
+        rtv: &rtv,
+        srv: None,
+        format: desc.Format,
+        extent,
+    };
+    let textures = PersistentTextures::new(device);
+    let single = vec![quad(0.0, 0.0, 24.0, 16.0, "#808080", 1.0, 0.0, 0.0)];
+    let mut layered = single.clone();
+    layered.extend([
+        PaintCommand::PushOpacity(0.5),
+        quad(0.0, 0.0, 12.0, 16.0, "#ff0000", 1.0, 0.0, 0.0),
+        quad(6.0, 0.0, 12.0, 16.0, "#0000ff", 1.0, 0.0, 0.0),
+        PaintCommand::PopOpacity,
+    ]);
+    let plans: Vec<_> = [&single, &single, &layered, &layered, &single]
+        .into_iter()
+        .map(|commands| plan_paint(extent, Oklch::TRANSPARENT, commands).unwrap())
+        .collect();
+    let mut outputs = Vec::new();
+    for legacy in [false, true] {
+        let mut renderer = SceneRenderer::new(device, None, SceneOptions::default()).unwrap();
+        if legacy {
+            renderer.constant_offsets = None;
+            renderer.constants = dynamic_buffer(
+                device,
+                (CONSTANT_FLOATS * 4) as u64,
+                D3D11_BIND_CONSTANT_BUFFER,
+                "constant_buffer",
+            )
+            .unwrap();
+        }
+        let frames: Vec<_> = plans
+            .iter()
+            .map(|plan| {
+                unsafe { context.ClearState() };
+                renderer
+                    .record(context, plan, &target, &textures, None)
+                    .unwrap();
+                read_texture(device, context, &texture, |bytes, pitch| {
+                    (0..extent.height as usize)
+                        .flat_map(|row| {
+                            bytes[row * pitch..row * pitch + extent.width as usize * 4].to_vec()
+                        })
+                        .collect::<Vec<_>>()
+                })
+                .unwrap()
+            })
+            .collect();
+        outputs.push(frames);
+    }
+    assert_ne!(outputs[0][0], outputs[0][2]);
+    assert_eq!(outputs[0], outputs[1]);
+}
